use std::{collections::{HashMap,HashSet},fs::{self,File},io::{Read,Write},path::Path,sync::atomic::{AtomicBool,Ordering}};
use zip::ZipArchive;
use crate::{CatalogEntry,PayloadError,PayloadManifest,PayloadProgress,Sha256Digest,SourceManifest};
pub(crate) fn extract(entry:&CatalogEntry,archive:&Path,destination:&Path,progress:&dyn Fn(PayloadProgress),cancel:&AtomicBool)->Result<(PayloadManifest,SourceManifest),PayloadError>{let file=File::open(archive).map_err(|e|PayloadError::io("open archive",archive.into(),e))?;let mut zip=ZipArchive::new(file).map_err(|e|PayloadError::Archive(e.to_string()))?;if zip.len() as u64>entry.file_count_limit(){return Err(PayloadError::LimitExceeded{subject:"archive file count",limit:entry.file_count_limit(),actual:zip.len()as u64})}let mut payload=zip.by_name("payload.json").map_err(|_|PayloadError::UnsafeArchive("archive has no payload.json".into()))?;if payload.size()>1024*1024{return Err(PayloadError::LimitExceeded{subject:"payload.json",limit:1024*1024,actual:payload.size()})}let mut bytes=Vec::new();payload.read_to_end(&mut bytes).map_err(|e|PayloadError::Archive(e.to_string()))?;let actual=Sha256Digest::hash_reader(bytes.as_slice())?;if actual!=*entry.payload_manifest_sha256(){return Err(PayloadError::DigestMismatch{subject:"payload.json".into(),expected:entry.payload_manifest_sha256().clone(),actual})}let manifest=PayloadManifest::parse_and_validate(&bytes,entry)?;drop(payload);let declared:HashMap<_,_>=manifest.files().iter().map(|file|(file.path(),file)).collect();let mut seen=HashSet::new();let mut expanded=0_u64;for index in 0..zip.len(){if cancel.load(Ordering::Relaxed){return Err(PayloadError::Cancelled)}let mut member=zip.by_index(index).map_err(|e|PayloadError::Archive(e.to_string()))?;let raw=std::str::from_utf8(member.name_raw()).map_err(|_|PayloadError::UnsafeArchive("non-UTF-8 entry name".into()))?;if raw=="payload.json"{continue}let enclosed=member.enclosed_name().ok_or_else(||PayloadError::UnsafeArchive(raw.into()))?;if member.is_dir()||raw.contains('\\')||!seen.insert(enclosed.clone()){return Err(PayloadError::UnsafeArchive(raw.into()))}let key=enclosed.to_str().ok_or_else(||PayloadError::UnsafeArchive(raw.into()))?;let expected=declared.get(key).ok_or_else(||PayloadError::UnsafeArchive(format!("undeclared archive entry {raw}")))?;if member.size()!=expected.size(){return Err(PayloadError::InvalidManifest(format!("size mismatch for {key}")))}expanded=expanded.checked_add(member.size()).ok_or(PayloadError::LimitExceeded{subject:"expanded size",limit:entry.expanded_size_limit(),actual:u64::MAX})?;if expanded>entry.expanded_size_limit(){return Err(PayloadError::LimitExceeded{subject:"expanded size",limit:entry.expanded_size_limit(),actual:expanded})}let output=destination.join(key);if let Some(parent)=output.parent(){fs::create_dir_all(parent).map_err(|e|PayloadError::io("create extraction directory",parent.into(),e))?}let mut target=File::options().write(true).create_new(true).open(&output).map_err(|e|PayloadError::io("create extracted file",output.clone(),e))?;let mut data=Vec::new();member.read_to_end(&mut data).map_err(|e|PayloadError::Archive(e.to_string()))?;target.write_all(&data).map_err(|e|PayloadError::io("write extracted file",output.clone(),e))?;target.sync_all().map_err(|e|PayloadError::io("flush extracted file",output.clone(),e))?;let got=Sha256Digest::hash_reader(data.as_slice())?;if got!=*expected.sha256(){return Err(PayloadError::DigestMismatch{subject:key.into(),expected:expected.sha256().clone(),actual:got})}progress(PayloadProgress::Extracting{files:seen.len()as u64,total:manifest.files().len()as u64});}if seen.len()!=declared.len(){return Err(PayloadError::InvalidManifest("archive does not contain every declared file".into()))}let source_bytes=fs::read(destination.join("sources.json")).map_err(|e|PayloadError::io("read extracted sources.json",destination.join("sources.json"),e))?;let sources=SourceManifest::parse_and_validate(&source_bytes,entry)?;Ok((manifest,sources))}
